from bisect import bisect_left
from typing import List

def findMaximumBeauty(arr: List[int]) -> int:
    # 下标 i（1-indexed）上的值 v 想在最终数组里落在位置 v，需要 d = i - v >= 0
    pts = sorted((i - v, v) for i, v in enumerate(arr, 1) if i - v >= 0)
    tails = []                      # 严格递增 LIS 的经典 tails 数组
    for _, v in pts:
        k = bisect_left(tails, v)
        if k == len(tails):
            tails.append(v)
        else:
            tails[k] = v
    return len(tails)
